// ===========================================================================
//  CẤU HÌNH - chỉnh ở đây
// ===========================================================================
// Danh sách mã cổ phiếu theo dõi (thêm/bớt tuỳ ý)
const WATCHLIST = ['VNM', 'FPT', 'HPG', 'MWG', 'VCB', 'SSI', 'DGC', 'VND', 'MBB', 'STB'];

// Đổi thành true để ÉP gửi tin nhắn test (hạ ngưỡng còn 0.1).
// ⚠️ Test xong nhớ đổi lại false, không là bị spam mỗi 15 phút!
const TEST_MODE = false;

const VOL_SPIKE  = TEST_MODE ? 0.1 : 2.0;  // KL hôm nay >= 2x trung bình 20 phiên
const PRICE_MOVE = TEST_MODE ? 0.1 : 3.0;  // |Thay đổi giá| >= 3% so với phiên trước
const LOOKBACK   = 20;                     // Số phiên tính trung bình khối lượng
// ===========================================================================

const to   = Math.floor(Date.now() / 1000);
const from = to - 60 * 60 * 24 * 90; // lấy 90 ngày để đủ > 20 phiên giao dịch

const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': '*/*',
};

// Nguồn chính: DNSE (Entrade). Dự phòng: VNDirect.
// Cả hai trả về các mảng song song t/o/h/l/c/v (TCBS cũ đã chết 404 từ 06/2026).
const fetchBars = async (ticker) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock',
      qs: { symbol: ticker, from, to, resolution: '1D' },
      headers,
      json: true,
    });
    if (res && Array.isArray(res.t) && res.t.length) return { src: 'DNSE', d: res };
  } catch (e) { /* rơi xuống nguồn dự phòng */ }

  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://dchart-api.vndirect.com.vn/dchart/history',
    qs: { symbol: ticker, resolution: 'D', from, to },
    headers: { ...headers, Referer: 'https://dchart.vndirect.com.vn/' },
    json: true,
  });
  if (res && Array.isArray(res.t) && res.t.length) return { src: 'VNDirect', d: res };
  throw new Error('cả 2 nguồn đều không có dữ liệu');
};

const alerts = [];
const debug  = [];

for (const ticker of WATCHLIST) {
  try {
    const { src, d } = await fetchBars(ticker);
    const n = d.t.length;
    debug.push(ticker + ': OK (' + src + ', ' + n + ' phiên)');
    if (n < 5) continue;

    const closes = d.c;
    const vols   = d.v;
    const todayClose = closes[n - 1];
    const todayVol   = vols[n - 1];
    const prevClose  = closes[n - 2];

    // Trung bình khối lượng các phiên trước (loại phiên hôm nay)
    const start   = Math.max(0, n - 1 - LOOKBACK);
    const histVol = vols.slice(start, n - 1);
    const avgVol  = histVol.reduce((s, v) => s + (v || 0), 0) / (histVol.length || 1);

    const volRatio = avgVol ? todayVol / avgVol : 0;
    const pct      = prevClose ? ((todayClose - prevClose) / prevClose) * 100 : 0;

    const reasons = [];
    if (volRatio >= VOL_SPIKE)       reasons.push('📈 KL đột biến x' + volRatio.toFixed(1));
    if (Math.abs(pct) >= PRICE_MOVE) reasons.push((pct >= 0 ? '🟢 Giá +' : '🔴 Giá ') + pct.toFixed(2) + '%');
    if (reasons.length) alerts.push({ ticker, close: todayClose, pct, volRatio, reasons });
  } catch (e) {
    debug.push(ticker + ': ❌ ' + (e.message || String(e)));
  }
}

// Tự nhận diện đơn vị giá: nguồn trả 64.5 (nghìn đồng) hay 64500 (đồng) đều hiển thị đúng
const fmtPrice = (c) => {
  const dong = c < 500 ? c * 1000 : c;
  return Math.round(dong).toLocaleString('vi-VN') + 'đ';
};

let message = '';
if (alerts.length) {
  const lines = alerts
    .sort((a, b) => Math.abs(b.pct) - Math.abs(a.pct))
    .map(a => '*' + a.ticker + '* — ' + fmtPrice(a.close) + '\n   ' + a.reasons.join('  |  '));
  const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
  message = (TEST_MODE ? '🧪 *TEST* — ' : '')
          + '🔔 *CẢNH BÁO CỔ PHIẾU BẤT THƯỜNG*\n_' + now + '_\n\n'
          + lines.join('\n\n')
          + '\n\n_Nguồn: DNSE/VNDirect · ' + alerts.length + ' mã_';
}

return [{ json: { hasAlerts: alerts.length > 0, count: alerts.length, message, debug } }];
